class Weird
{
    public static bool operator ==(Weird? a, Weird? b) => true;
    public static bool operator !=(Weird? a, Weird? b) => false;
}

Weird w = new();
Console.WriteLine(w == null);   // True — the operator said so
Console.WriteLine(w is null);   // False — an honest check

